node.warn(`[${msg.requestId}] Getting water pump status`);

// Get state from GLOBAL context
const state = global.get('water_pump_state') || {};

// Build status message
let statusText = '💧 *Water Pump Status*\n\n';

// Pump Power
const pumpStatus = state.pump_power || 'UNKNOWN';
const pumpIcon = pumpStatus === 'ON' ? '🟢' : pumpStatus === 'OFF' ? '⚫' : '❓';
statusText += `${pumpIcon} *Pump Power*: ${pumpStatus}\n`;

// Drain Water
const drainStatus = state.drain_water || 'UNKNOWN';
const drainIcon = drainStatus === 'ON' ? '🟢' : drainStatus === 'OFF' ? '⚫' : '❓';
statusText += `${drainIcon} *Drain Water*: ${drainStatus}\n`;

// Feed Trench 1
const trench1Status = state.feed_trench_1 || 'UNKNOWN';
const trench1Icon = trench1Status === 'ON' ? '🟢' : trench1Status === 'OFF' ? '⚫' : '❓';
statusText += `${trench1Icon} *Feed Trench 1*: ${trench1Status}\n`;

// Feed Trench 2
const trench2Status = state.feed_trench_2 || 'UNKNOWN';
const trench2Icon = trench2Status === 'ON' ? '🟢' : trench2Status === 'OFF' ? '⚫' : '❓';
statusText += `${trench2Icon} *Feed Trench 2*: ${trench2Status}\n`;

if (state.lastUpdate) {
    const lastUpdate = new Date(state.lastUpdate).toLocaleString('ro-RO');
    statusText += `\n🕐 Last update: ${lastUpdate}`;
}

const inlineKeyboard = {
    inline_keyboard: [
        [{ text: '💧 Start Pump', callback_data: '/pump_start' }, { text: '⏹️ Stop Pump', callback_data: '/pump_stop' }],
        [{ text: '🚰 Drain Water', callback_data: '/pump_drain' }],
        [{ text: '🔄 Refresh Status', callback_data: '/pump_status' }]
    ]
};

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: statusText,
    options: {
        parse_mode: 'Markdown',
        reply_markup: inlineKeyboard
    }
};

return msg;

